// An electric motorcycle with a 4-speed gearbox and a clutch, without its body panels, on a roller test bench (our own design, no
// maker's name or badge). Units: cm. X: forward (the front wheel at +X), Y: up (the bench top at 0), Z: the rider's right (+Z).
// The chain, the gear lever and the clutch lever are on the left (-Z); the throttle grip, the front brake lever and the clutch cover on the right (+Z).
const S = W.store;
S.alloy = W.metal('#c3cad1', { rough: 0.3 });
S.dark = W.metal('#2b3036', { rough: 0.38 });
S.black = W.paint('#1b1e22', { metallic: 0.3, rough: 0.45 });
S.rub = W.rubber('#17181a');
S.hv = W.plastic('#ff7a1a', { rough: 0.5 });     // (high voltage cables are orange on every EV)
S.cyan = W.glow('#4fd2ff', 1.4);
S.st = { v: 0, rpm: 0, free: 0, wh: 4000, km: 0, used: 0, avg: 38, inst: 0, p: 0, regen: 0, gear: 1, shiftT: -9, engaged: true, ang: 0, chain: 0, last: 1 };
const b = W.group();
b.add(W.mesh(W.box(190, 10, 70, 1), W.paint('#3a3f46', { metallic: 0.2, rough: 0.6 }), { at: [0, -5, 0] }));
for (const x of [-66.5, -46.5]) b.add(W.mesh(W.cyl(7, 7, 40, 40), W.metal('#8c939b', { rough: 0.35 }), { at: [x, -1.47, 0], rot: [90, 0, 0] })); // two rollers under the back wheel
b.add(W.mesh(W.box(36, 0.4, 44, 0.1), W.metal('#15171a'), { at: [-56.5, 0.05, 0] }));          // the pit the rollers turn in
b.add(W.mesh(W.box(34, 4.2, 22, 0.8), W.paint('#4a5058', { metallic: 0.2, rough: 0.6 }), { at: [76, 2.1, 0] }));  // the front wheel's plate
for (const z of [-34, 34]) b.add(W.mesh(W.box(186, 0.6, 1.2), W.glow('#ffc14a', 0.8), { at: [0, 0.3, z] }));
S.rollers = [];
W.add(b, { label: 'టెస్ట్ బెంచ్' });
S.rollerGroup = b;
// a wheel: a tyre, a black rim with five spokes, a hub; axis Z
S.wheel = (rOut, w, rim) => {
  const g = W.group();
  const t = (rOut - rim) / 2;
  const tyre = W.mesh(W.torus(rim + t, t, 72, 18), S.rub);
  tyre.scale.z = (w / 2) / t;
  g.add(tyre);
  for (let i = 0; i < 36; i++) { // tread blocks
    const a = (i / 36) * Math.PI * 2;
    g.add(W.mesh(W.box(2.4, 0.5, w * 0.6), S.rub, { at: [Math.cos(a) * (rOut - 0.1), Math.sin(a) * (rOut - 0.1), 0], rot: [0, 0, a * 180 / Math.PI + 90] }));
  }
  g.add(W.mesh(W.ring(rim - 1.8, rim + 0.2, w * 0.62, 72), S.black, { rot: [90, 0, 0] }));
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    for (const d of [-0.16, 0.16]) g.add(W.mesh(W.box(rim - 5, 1.5, 1.2, 0.4), S.black, { at: [Math.cos(a + d) * (rim / 2 + 1.5), Math.sin(a + d) * (rim / 2 + 1.5), 0], rot: [0, 0, (a + d) * 180 / Math.PI] }));
  }
  g.add(W.mesh(W.cyl(5, 5, w * 0.85, 32), S.alloy, { rot: [90, 0, 0] }));
  const blur = new THREE.Mesh(new THREE.CircleGeometry(rim - 1.8, 48), new THREE.MeshBasicMaterial({ color: 0x0c0d0f, transparent: true, opacity: 0, depthWrite: false }));
  for (const z of [-w * 0.32, w * 0.32]) { const m = blur.clone(); m.position.z = z; g.add(m); }
  g.userData.blur = blur.material;
  return g;
};
// a toothed sprocket, axis Z
S.sprocket = (teeth, r, mat) => W.mesh(W.gear({ teeth, r, depth: 0.6, hole: r * 0.35 }), mat, { rot: [90, 0, 0] });
// a brake disc with holes, axis Z
S.disc = (rIn, rOut) => {
  const g = W.group();
  g.add(W.mesh(W.ring(rIn, rOut, 0.5, 64), W.metal('#b9bec4', { rough: 0.28 }), { rot: [90, 0, 0] }));
  for (let i = 0; i < 18; i++) { const a = i / 18 * Math.PI * 2; g.add(W.mesh(W.cyl(0.45, 0.45, 0.62, 10), S.dark, { at: [Math.cos(a) * (rIn + rOut) / 2, Math.sin(a) * (rIn + rOut) / 2, 0], rot: [90, 0, 0] })); }
  return g;
};

const S = W.store;
// the back wheel (17", 140 mm tyre) on the rollers, with its 44-tooth sprocket (left) and brake disc (right); the front wheel (17", 100 mm) in its chock
const rear = W.group({ at: [-56.5, 31.4 + 4.2, 0] });
const rw = S.wheel(31.4, 14, 21.6);
rear.add(rw);
const rs = S.sprocket(44, 10.5, W.metal('#9aa1a8', { rough: 0.3 })); rs.position.z = -8.6; rw.add(rs);
const rd = S.disc(7, 11); rd.position.z = 8.2; rw.add(rd);
W.add(rear, { label: 'వెనక చక్రం', explode: [-50, 0, -10], heat: [30, 36], layer: 1 });
S.rearWheel = rw;
const front = W.group({ at: [76, 29.6 + 4.2, 0] });
const fw = S.wheel(29.6, 10.5, 21.6);
front.add(fw);
const fd = S.disc(10, 15); fd.position.z = 5.6; fw.add(fd);
front.add(W.mesh(W.box(5, 7, 3.2, 0.6), W.metal('#c9a24a', { rough: 0.35 }), { at: [-4, 12, 5.6] }));  // the brake caliper
W.add(front, { label: 'ముందు చక్రం', explode: [48, 0, -10], layer: 1 });
S.frontWheel = fw;

const S = W.store;
const Y = 4.2; // (everything sits on the bench)
const f = W.group({ at: [0, Y, 0] });
const fm = W.paint('#8f99a3', { metallic: 0.5, rough: 0.35 });
const tube = (pts, r = 1.4) => f.add(W.mesh(W.tube(pts, r, 48), fm));
for (const z of [-1, 1]) {
  tube([[50, 92, z * 6], [30, 86, z * 11], [5, 80, z * 12.5], [-12, 74, z * 12.5]]);                 // top rails over the battery
  tube([[50, 86, z * 5], [44, 66, z * 11], [36, 44, z * 12.5], [24, 22, z * 12.5]]);                 // down rails in front of it
  tube([[24, 22, z * 12.5], [4, 18, z * 12.5], [-16, 22, z * 12.5], [-26, 40, z * 12.5]], 1.3);     // the cradle under the motor
  tube([[-12, 74, z * 12.5], [-24, 60, z * 12.5], [-26, 40, z * 12.5]]);                            // down to the swingarm pivot
  tube([[-12, 74, z * 10], [-40, 82, z * 9], [-66, 86, z * 7]], 1.1);                               // the seat's subframe
  tube([[-26, 46, z * 11], [-46, 70, z * 9], [-60, 84, z * 7.5]], 1.0);
}
f.add(W.mesh(W.cyl(3.2, 3.2, 14, 32), fm, { at: [49, 91, 0], rot: [0, 0, 20] }));  // the steering head
f.add(W.mesh(W.cyl(2.2, 2.2, 28, 24), S.alloy, { at: [-26, 40, 0], rot: [90, 0, 0] })); // the swingarm pivot bolt
W.add(f, { label: 'ఫ్రేమ్', explode: [0, 30, -8], heat: [30, 34], layer: 0 });
const seat = W.group({ at: [0, Y, 0] });
const ss = new THREE.Shape();
ss.moveTo(-68, 0); ss.quadraticCurveTo(-70, 5, -64, 7); ss.lineTo(-30, 6); ss.quadraticCurveTo(-14, 6, -8, 2); ss.lineTo(-8, 0); ss.lineTo(-68, 0);
seat.add(W.mesh(new THREE.ExtrudeGeometry(ss, { depth: 24, bevelEnabled: true, bevelSize: 1.5, bevelThickness: 1.5, bevelSegments: 3 }).translate(0, 0, -12), W.fabric('#222428'), { at: [0, 83.5, 0] }));
W.add(seat, { label: 'సీటు', explode: [-6, 52, -8], layer: 0 });

const S = W.store;
const Y = 4.2;
// the fork from the steering head down to the front axle; the handlebar with the grips, the levers and the screen
const fk = W.group({ at: [0, Y, 0] });
for (const z of [-9, 9]) {
  fk.add(W.mesh(W.tube([[48, 97, z], [76, 29.6, z]], 2.6, 8), W.metal('#d9b45a', { rough: 0.3 })));      // gold fork legs
  fk.add(W.mesh(W.tube([[52.5, 86, z], [62, 63, z]], 3.4, 8), S.dark));                                   // the upper tubes
}
for (const y of [97, 87]) fk.add(W.mesh(W.box(9, 2.4, 24, 0.6), S.alloy, { at: [48 + (97 - y) * 0.36, y, 0] }));
fk.add(W.mesh(W.cyl(1, 1, 22, 12), S.alloy, { at: [76, 29.6, 0], rot: [90, 0, 0] }));
W.add(fk, { label: 'ముందు ఫోర్క్', explode: [44, 6, -10], layer: 1 });
const h = W.group({ at: [0, Y, 0] });
h.add(W.mesh(W.tube([[44, 101, -36], [46, 102, -20], [47, 100, 0], [46, 102, 20], [44, 101, 36]], 1.1, 40), W.metal('#2b2f35', { rough: 0.3 })));
const grip = (z) => { const g = W.group({ at: [44, 101, z] }); g.add(W.mesh(W.cyl(1.7, 1.7, 12, 24), S.rub, { rot: [90, 0, 0] })); return g; };
const gl = grip(-30), gr = grip(30);
gr.add(W.mesh(W.box(0.6, 0.5, 11, 0.1), W.plastic('#f2f2f2'), { at: [0, 1.75, 0] }));   // a white line: see the grip turn
h.add(gl, gr);
const lever = (z, side) => { const p = W.group({ at: [47, 102, z] }); p.add(W.mesh(W.box(1.2, 0.8, 16, 0.3), S.alloy, { at: [2.5, -0.8, side * 8] })); return p; };
const cl = lever(-22, -1), bl = lever(22, 1);   // clutch lever (left), front brake lever (right)
h.add(cl, bl);
// the screen: speed, gear, battery, range
const dash = W.canvasTex(256, 160);
const dm = new THREE.MeshStandardMaterial({ map: dash.texture, emissiveMap: dash.texture, emissive: 0xffffff, emissiveIntensity: 1, roughness: 0.2 });
const dh = W.group({ at: [43, 106, 0], rot: [0, -90, 0] });
dh.add(W.mesh(W.box(19, 13, 2.4, 0.8), S.black, { at: [0, 0, -1.3] }));
dh.add(W.mesh(new THREE.PlaneGeometry(17, 10.6), dm));
dh.rotation.x = 0; dh.rotateX(-0.45);
h.add(dh);
S.dashDraw = (st, warn) => {
  const g = dash.ctx;
  g.fillStyle = '#05080b'; g.fillRect(0, 0, 256, 160);
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillStyle = '#f1f5f9'; g.font = '700 74px system-ui, sans-serif'; g.fillText(String(Math.round(st.v)), 104, 70);
  g.fillStyle = '#8aa0b4'; g.font = '600 18px system-ui, sans-serif'; g.fillText('km/h', 104, 116);
  g.strokeStyle = '#4fd2ff'; g.lineWidth = 3; g.strokeRect(198, 22, 46, 54);
  g.fillStyle = '#4fd2ff'; g.font = '700 40px system-ui, sans-serif'; g.fillText(st.gear >= 1 && st.gear <= 4 ? String(st.gear) : 'N', 221, 50);
  const soc = Math.max(0, Math.min(1, st.wh / 5000));
  g.fillStyle = '#1c2630'; g.fillRect(16, 136, 160, 12);
  g.fillStyle = soc < 0.2 ? '#ff5a3c' : '#5ee38f'; g.fillRect(16, 136, 160 * soc, 12);
  g.fillStyle = '#cfd8e1'; g.font = '600 16px system-ui, sans-serif'; g.textAlign = 'left';
  g.fillText(Math.round(soc * 100) + '%', 182, 142);
  g.textAlign = 'center'; g.fillText(Math.round(st.range) + ' km', 221, 100);
  if (st.regen > 1) { g.fillStyle = '#5ee38f'; g.font = '700 16px system-ui, sans-serif'; g.fillText('REGEN', 40, 18); }
  if (warn) { g.fillStyle = '#ff5a3c'; g.font = '700 16px system-ui, sans-serif'; g.fillText('HOT', 120, 18); }
  dash.update();
};
S.dashDraw({ v: 0, gear: 1, wh: 4000, range: 105, regen: 0 }, false);
W.add(h, { label: 'హ్యాండిల్ బార్', explode: [24, 42, -10], layer: 0 });
S.grip = gr; S.clutchLever = cl; S.brakeLever = bl;
const hl = W.group({ at: [57, 88 + Y, 0], rot: [0, 0, -8] });
hl.add(W.mesh(W.cyl(8, 9, 6, 48), S.black, { rot: [0, 0, 90] }));
hl.add(W.mesh(W.cyl(7.2, 7.2, 0.4, 48), W.glow('#eaf6ff', 2.2), { at: [3.1, 0, 0], rot: [0, 0, 90] }));
hl.add(W.mesh(W.torus(7.4, 0.35, 48, 6), S.cyan, { at: [3.2, 0, 0], rot: [0, 90, 0] }));
W.add(hl, { label: 'హెడ్‌లైట్', explode: [44, 22, -6], layer: 0 });

const S = W.store;
const Y = 4.2;
// the 5 kWh pack between the frame rails, cooled by liquid through a plate under it; the BMS board on top; the charging port in front
const bt = W.group({ at: [12, 61 + Y, 0] });
bt.add(W.mesh(W.box(44, 28, 23, 2), W.paint('#20262d', { metallic: 0.4, rough: 0.4 })));
for (let i = 0; i < 9; i++) bt.add(W.mesh(W.box(40, 0.8, 23.4, 0.3), S.dark, { at: [0, -12 + i * 3, 0] }));  // cooling ribs
const t1 = W.text('5 kWh · LIQUID COOLED', { size: 1.5, color: '#9fe6ff', spacing: 2 });
t1.position.set(0, 4, 11.75);
bt.add(t1);
const t2 = t1.clone(); t2.position.z = -11.75; t2.rotation.y = Math.PI; bt.add(t2);
bt.add(W.mesh(W.box(46, 1.6, 25, 0.6), W.metal('#7d8790', { rough: 0.35 }), { at: [0, -14.6, 0] }));   // the cold plate
W.add(bt, { label: 'బ్యాటరీ ప్యాక్ 5 kWh', explode: [0, 62, -34], heat: [30, 44], layer: 1 });
const bm = W.group({ at: [8, 76.5 + Y, 0] });
bm.add(W.mesh(W.box(16, 2.4, 11, 0.5), W.plastic('#14532d', { rough: 0.5 })));
for (let i = 0; i < 6; i++) bm.add(W.mesh(W.box(1.4, 0.8, 1.4, 0.2), W.plastic('#0e0f11'), { at: [-5 + i * 2, 1.4, -2] }));
const led = W.glow('#5ee38f', 2);
bm.add(W.mesh(W.sphere(0.5, 12), led, { at: [6, 1.5, 3] }));
W.add(bm, { label: 'BMS బోర్డ్', explode: [0, 84, -34], heat: [30, 40], layer: 1 });
S.bmsLed = led;
const cp = W.group({ at: [32, 77 + Y, 0], rot: [0, 0, 12] });
cp.add(W.mesh(W.cyl(3.4, 3.8, 3, 40), S.black));
cp.add(W.mesh(W.torus(2.6, 0.3, 40, 8), S.cyan, { at: [0, 1.55, 0], rot: [90, 0, 0] }));
for (let i = 0; i < 5; i++) cp.add(W.mesh(W.cyl(0.35, 0.35, 0.6, 10), S.alloy, { at: [Math.cos(i * 1.256) * 1.3, 1.6, Math.sin(i * 1.256) * 1.3] }));
W.add(cp, { label: 'చార్జింగ్ పోర్ట్', explode: [26, 74, -20], layer: 0 });

const S = W.store;
const Y = 4.2;
// the motor (its cover, the copper stator, the magnet rotor), the clutch, the 4-speed gearbox with its gears, the 14-tooth front sprocket
const mo = W.group({ at: [6, 34 + Y, 0] });
mo.add(W.mesh(W.cyl(11, 11, 15, 64), W.metal('#3a4048', { rough: 0.32 }), { rot: [90, 0, 0] }));
for (let i = 0; i < 16; i++) { const a = i / 16 * Math.PI * 2; mo.add(W.mesh(W.box(1, 1, 15.4, 0.2), S.dark, { at: [Math.cos(a) * 11, Math.sin(a) * 11, 0] })); }
const mt = W.text('MOTOR · 10 kW', { size: 1.2, color: '#d6dde4', spacing: 2 });
mt.position.set(0, 0, 7.55);
mo.add(mt);
W.add(mo, { label: 'మోటార్', explode: [14, -16, 26], heat: [32, 72], layer: 0 });
const stt = W.group({ at: [6, 34 + Y, 0] });
stt.add(W.mesh(W.ring(6.4, 9.8, 12, 64), W.metal('#6b7178'), { rot: [90, 0, 0] }));
for (let i = 0; i < 12; i++) { const a = i / 12 * Math.PI * 2; stt.add(W.mesh(W.box(2.6, 2.2, 13, 0.6), W.metal('copper', { rough: 0.3 }), { at: [Math.cos(a) * 7.6, Math.sin(a) * 7.6, 0], rot: [0, 0, a * 180 / Math.PI] })); }
W.add(stt, { label: 'మోటార్ స్టేటర్', explode: [34, -16, 30], heat: [35, 92], layer: 1 });
const rot = W.group({ at: [6, 34 + Y, 0] });
const rr = W.group();
rr.add(W.mesh(W.cyl(5.8, 5.8, 12, 48), W.metal('#9aa1a8', { rough: 0.3 }), { rot: [90, 0, 0] }));
for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; rr.add(W.mesh(W.box(2.8, 0.7, 11.6, 0.15), W.paint(i % 2 ? '#d64545' : '#3b6fd6', { metallic: 0.4 }), { at: [Math.cos(a) * 5.9, Math.sin(a) * 5.9, 0], rot: [0, 0, a * 180 / Math.PI + 90] })); }
rr.add(W.mesh(W.cyl(1.2, 1.2, 22, 16), S.alloy, { rot: [90, 0, 0] }));
rot.add(rr);
W.add(rot, { label: 'మోటార్ రోటర్', explode: [54, -16, 34], heat: [35, 80], layer: 2 });
S.rotor = rr;
const gb = W.group({ at: [-12, 36 + Y, 0] });
const gbx = new THREE.Shape();
gbx.moveTo(-10, -8); gbx.lineTo(8, -9); gbx.quadraticCurveTo(13, 0, 8, 9); gbx.lineTo(-8, 9); gbx.quadraticCurveTo(-13, 0, -10, -8);
gb.add(W.mesh(new THREE.ExtrudeGeometry(gbx, { depth: 15, bevelEnabled: true, bevelSize: 0.8, bevelThickness: 0.8, bevelSegments: 2 }).translate(0, 0, -7.5), W.metal('#b5bcc3', { rough: 0.4 })));
const fs = S.sprocket(14, 3.9, W.metal('#9aa1a8', { rough: 0.3 })); fs.position.set(-7, 1, -9.2); gb.add(fs);
S.frontSprocket = fs;
const gt = W.text('4-SPEED', { size: 1.1, color: '#2b3036', spacing: 2 });
gt.position.set(0, 4, 8.35);
gb.add(gt);
W.add(gb, { label: 'గేర్‌బాక్స్ 4 స్పీడ్', explode: [-16, -18, 26], heat: [30, 56], layer: 0 });
const gears = W.group({ at: [-12, 36 + Y, 0] });
S.gearSet = [];
const gm = W.metal('#d0d5da', { rough: 0.25 });
for (let i = 0; i < 4; i++) { // input shaft (top) and output shaft (bottom): four pairs, one pair per gear
  const z = -5 + i * 3.2, ri = 2 + i * 0.8, ro = 6.6 - i * 0.8;
  const a = W.mesh(W.gear({ teeth: 10 + i * 4, r: ri, depth: 1.6 }), gm, { at: [3, 3.6, z], rot: [90, 0, 0] });
  const c = W.mesh(W.gear({ teeth: 34 - i * 4, r: ro, depth: 1.6 }), gm, { at: [3 - (ri + ro) * 0.0, 3.6 - (ri + ro) + 0.4, z], rot: [90, 0, 0] });
  gears.add(a, c);
  S.gearSet.push({ a, c, k: ri / ro });
}
gears.add(W.mesh(W.cyl(0.8, 0.8, 17, 12), S.alloy, { at: [3, 3.6, 0], rot: [90, 0, 0] }));
W.add(gears, { label: 'గేర్లు', explode: [-36, -18, 30], heat: [30, 60], layer: 1 });
const cc = W.group({ at: [-4, 38 + Y, 9.2] });
cc.add(W.mesh(W.cyl(7.2, 7.6, 3, 56), W.metal('#c9ced3', { rough: 0.3 }), { rot: [90, 0, 0] }));
for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2; cc.add(W.mesh(W.cyl(0.5, 0.5, 0.6, 10), S.dark, { at: [Math.cos(a) * 6.2, Math.sin(a) * 6.2, 1.6], rot: [90, 0, 0] })); }
const ct = W.text('CLUTCH', { size: 1, color: '#2b3036', spacing: 2 });
ct.position.set(0, 0, 1.55);
cc.add(ct);
W.add(cc, { label: 'క్లచ్', explode: [-4, -30, 40], heat: [30, 50], layer: 0 });
const lv = W.group({ at: [-14, 26 + Y, -13] });
const lvr = W.group();
lvr.add(W.mesh(W.box(16, 1.2, 1.2, 0.3), S.dark, { at: [7, 0, 0] }));
lvr.add(W.mesh(W.cyl(0.8, 0.8, 4, 12), S.rub, { at: [15, 0, -1.6], rot: [90, 0, 0] }));
lv.add(lvr);
W.add(lv, { label: 'గేర్ లివర్', explode: [0, -26, 30], layer: 0 });
S.shiftLever = lvr;

const S = W.store;
const Y = 4.2;
// the swingarm from the pivot to the back axle, the shock absorber, and the chain around the two sprockets (it moves with the wheel)
const sa = W.group({ at: [0, Y, 0] });
for (const z of [-12.5, 12.5]) sa.add(W.mesh(W.tube([[-26, 40, z], [-40, 36.5, z * 1.05], [-56.5, 31.4, z]], 1.9, 24), S.alloy));
sa.add(W.mesh(W.box(4, 4, 24, 0.8), S.alloy, { at: [-34, 38, 0] }));
sa.add(W.mesh(W.cyl(1.1, 1.1, 27, 12), S.alloy, { at: [-56.5, 31.4, 0], rot: [90, 0, 0] }));
W.add(sa, { label: 'స్వింగ్ ఆర్మ్', explode: [-30, -12, -14], layer: 1 });
const sh = W.group({ at: [0, Y, 0] });
const from = new THREE.Vector3(-36, 39, 0), to = new THREE.Vector3(-22, 74, 0);
const mid = from.clone().add(to).multiplyScalar(0.5), len = from.distanceTo(to);
